// vi/fil/af/sw — core UI ships natively from T (i18n.ts); these v2 blocks
// are filled with native strings via Object.assign after declaration (see
// below). Until a key is present here, v2() falls back to English.
const vi: Partial<V2Strings> = {};
const fil: Partial<V2Strings> = {};
const af: Partial<V2Strings> = {};
const sw: Partial<V2Strings> = {};
// Chinese variants use camelCase const names (hyphens aren't valid
// identifiers); they map to the "zh-CN"/"zh-TW" Lang codes in TABLES below.
const zhCN: Partial<V2Strings> = {};
const zhTW: Partial<V2Strings> = {};
const ko: Partial<V2Strings> = {};
const th: Partial<V2Strings> = {};
const bn: Partial<V2Strings> = {};
const da: Partial<V2Strings> = {};
const hu: Partial<V2Strings> = {};
const xh: Partial<V2Strings> = {};
const nso: Partial<V2Strings> = {};
const tn: Partial<V2Strings> = {};
const st: Partial<V2Strings> = {};
const ts: Partial<V2Strings> = {};
const ss: Partial<V2Strings> = {};
const ve: Partial<V2Strings> = {};
const nr: Partial<V2Strings> = {};

const TABLES: Record<Lang, Partial<V2Strings>> = {
  // uk/tr/pl/fa/id: core UI ships from T (i18n.ts); v2 long-tail strings
  // fall back to English via v2() until translated.
  uk, tr, pl, fa, id, nl, el, zu, vi, fil, af, sw,
  "zh-CN": zhCN, "zh-TW": zhTW, ko, th, bn, da, hu,
  xh, nso, tn, st, ts, ss, ve, nr,
  en,
  he,
  ar,
  ru,
  es,
  pt,
  fr,
  de,
  cs,
  sk,
  it,
  ja,
  hi,
  am,
};

/**
 * Resolve a V2 string for a given language.
 * Falls back to English when the locale has no entry — keeps the site
 * coherent in ru/es/pt/fr while we finish translating those.
 *
 * For template entries (functions), pass the arg as the third param.
 */
export function v2<K extends keyof V2Strings>(
  lang: Lang,
  key: K,
  ...args: Array<string | number>
): string {
  const locale = TABLES[lang] ?? {};
  const val = locale[key] ?? en[key];
  if (typeof val === "function") {
    // Accept any number of args — Template1 takes one, the multi-arg
    // templates (quizQuestionNofM, quizFinalScoreTemplate) take two.
    // Function casts let us call them uniformly without losing types
    // at the consumer side.
    return (val as (...a: Array<string | number>) => string)(...args);
  }
  return val as string;
}


